    for color, comp in components:
        min_r = min(p[0] for p in comp)
        min_c = min(p[1] for p in comp)
        norm = frozenset((p[0] - min_r, p[1] - min_c) for p in comp)
        shape_groups[norm].append((color, comp))

    # For each shape, recolor to minimum color among colors in that shape group
    result = [row[:] for row in grid]

